INSERT INTO `questions`(`id`,`test_id`,`question_text`,`reference_answer`,`grading_criteria`,`max_score`,`sort_order`) VALUES 
( '1', '1', 'Explain the differences between let, const, and var in JavaScript. Describe when you would use each one.', 'var declares a function-scoped or globally scoped variable and can be redeclared and reassigned. let is block-scoped, can be reassigned, but cannot be redeclared in the same scope. const is block-scoped and cannot be reassigned after initialization, although objects and arrays declared with const can still have their contents modified. In modern JavaScript, const is generally preferred when the variable reference will not change, let is used when reassignment is necessary, and var is usually avoided in new code because of its function scope and redeclaration behavior.', 'Award up to 10 points. Full credit should explain scope differences between var, let, and const; reassignment; redeclaration; and appropriate use cases. The answer should recognize that let and const are block-scoped while var is function-scoped or global. It should also recognize that const prevents reassignment of the variable reference, not necessarily mutation of an object or array. Partial credit should be awarded for answers that correctly explain some but not all differences. Minor terminology mistakes should not result in a large deduction if the underlying concept is correct.', '10.00', '1' ),
( '2', '1', 'Explain what async and await do in JavaScript. Give an example of a situation where asynchronous programming would be necessary.', 'async and await provide a cleaner way to work with Promises in JavaScript. Declaring a function with async causes it to return a Promise. The await keyword pauses execution inside that async function until a Promise settles, allowing asynchronous code to be written in a style similar to synchronous code. Asynchronous programming is useful when an operation takes time and should not block the application, such as making an HTTP request, querying a server, reading a file, or waiting for a timer.', 'Award up to 10 points. Full credit should explain that async functions work with Promises, that await waits for a Promise result inside an async function, and that asynchronous programming prevents long-running operations from blocking normal application execution. The answer must include at least one reasonable asynchronous example such as an API request, database/server operation, file access, or timer. Partial credit should be given if the student understands the general purpose but does not accurately explain Promises or await behavior.', '10.00', '2' ),
( '3', '1', 'What is the difference between an object and an array in JavaScript? Explain when you would choose one over the other.', 'A JavaScript object stores values as named properties using key-value pairs, while an array stores an ordered collection of values identified primarily by numeric indexes. Objects are useful for representing entities with named attributes, such as a user with a name and email. Arrays are useful for collections or lists where order and iteration are important, such as a list of users or products. Arrays are technically objects in JavaScript, but they provide specialized behavior and methods for ordered collections.', 'Award up to 10 points. Full credit should identify objects as key-value or named-property structures and arrays as ordered collections accessed primarily by indexes. The answer should explain an appropriate use case for each. Bonus understanding may include recognizing that arrays are technically objects in JavaScript, but this is not required for full credit. Partial credit should be given when the distinction is generally correct but examples or use cases are incomplete.', '10.00', '3' ),
( '4', '1', 'Explain what variable scope means in JavaScript. Describe the difference between global, function, and block scope.', 'Scope determines where a variable can be accessed in a JavaScript program. A global variable is accessible from many parts of the application, depending on how it is declared and the execution environment. Function scope means a variable is accessible throughout the function in which it is declared; var uses function scope. Block scope means a variable is limited to a block such as an if statement, loop, or other braces; let and const use block scope. Using narrower scopes helps prevent unintended access or modification of variables.', 'Award up to 10 points. Full credit should define scope and correctly explain global scope, function scope, and block scope. The answer should associate var with function scope and let/const with block scope. The student should demonstrate that scope determines where variables are accessible. Partial credit should be given when the general idea is correct but one type of scope is missing or incorrectly described.', '10.00', '4' ),
( '5', '1', 'What is an Ext JS component? Give examples of different components and explain how components are used to build an Ext JS application.', 'An Ext JS component is a reusable user interface building block managed by the Ext JS component system. Components can include panels, buttons, forms, text fields, windows, tabs, trees, and grids. Applications are built by creating and configuring components and arranging them using containers and layouts. Components can contain other components, expose configuration options, respond to events, and interact with application data and controllers or view models.', 'Award up to 10 points. Full credit should describe an Ext JS component as a reusable UI building block and provide multiple valid examples such as panels, buttons, fields, forms, windows, or grids. The answer should explain that components are configured and combined through containers or layouts to construct an application. Partial credit should be awarded if the student understands components but gives few examples or does not explain how they are assembled into an application.', '10.00', '5' ),
( '6', '1', 'Explain the purpose of an Ext JS DataGrid. Describe how data gets from a data source into the rows and columns displayed by the grid.', 'An Ext JS DataGrid displays structured tabular data in rows and columns and can provide functionality such as sorting, filtering, selection, editing, grouping, and paging. Typically, a data source is accessed through an Ext JS Store. The Store contains Model records representing individual data items. The grid is bound or configured with the Store, and grid columns specify which Model fields should be displayed. When the Store loads or changes, the grid renders the corresponding records into rows and field values into columns.', 'Award up to 10 points. Full credit should explain the DataGrid as a tabular data component and describe the data flow from a data source into a Store, from Store records or Models into grid rows, and from fields into configured columns. Exact Ext JS API terminology is helpful but equivalent explanations are acceptable. Partial credit should be awarded when the student understands the grid but omits Models, Stores, columns, or the data-loading flow.', '10.00', '6' ),
( '7', '1', 'Explain the roles of Models and Stores in Ext JS. How do they work together when displaying or modifying application data?', 'An Ext JS Model defines the structure and behavior of an individual data record, including fields and potentially validation, associations, or other record-related behavior. A Store manages a collection of Model records and can load, filter, sort, group, add, update, and remove records. UI components such as grids can bind to a Store. When the Store loads data, it creates or manages Model instances, and when records are modified the Store and associated data components can reflect those changes.', 'Award up to 10 points. Full credit should identify a Model as representing the structure or individual record and a Store as managing a collection of records. The answer should explain that Stores load and manage data and that components such as grids use Stores to display that data. It should also explain at a high level how Models and Stores work together when data changes. Partial credit should be given if one role is explained correctly but the relationship between them is incomplete.', '10.00', '7' ),
( '8', '1', 'Explain how events work in Ext JS. For example, describe how you could respond when a user selects a row in a DataGrid or clicks a button.', 'Ext JS components fire events when actions or state changes occur. Application code can register listeners or handlers for these events and execute logic in response. For example, a button can fire a click event and a handler can perform an action. A grid or its selection model can fire a selection-related event when the user selects a row, and a handler can inspect the selected record and update another component or perform another operation. Event handlers may be configured directly on components or managed through controllers and related application patterns.', 'Award up to 10 points. Full credit should explain that Ext JS components emit or fire events and that listeners or event handlers respond to those events. The answer should include a valid example such as responding to a button click or grid row selection. It should demonstrate understanding that the event handler can access relevant component or record information and execute application logic. Partial credit should be given for a generally correct event-driven explanation even if exact event names are not provided.', '10.00', '8' ),
( '9', '2', 'Explain the difference between application-level instructions and user input when working with an OpenAI model. Why is it useful to keep these responsibilities separate?', 'Application-level instructions define the general behavior, rules, role, constraints, or output expectations the application wants the model to follow. User input contains the specific request or information provided for an individual interaction. Keeping them separate allows the application to consistently enforce its intended behavior while still accepting changing user requests. It also makes prompts easier to maintain and helps prevent user content from being confused with the application\'s core instructions.', 'Award up to 10 points. Full credit should distinguish persistent or application-controlled instructions from request-specific user input. The answer should explain at least one benefit of separation, such as consistency, maintainability, security, control of behavior, or reducing ambiguity. Exact API field names are not required. Partial credit should be given when the student understands the distinction but provides little explanation of why it matters.', '10.00', '1' ),
( '10', '2', 'An application needs the model to return a score, summary, list of strengths, and list of weaknesses. Explain why returning structured data such as JSON is preferable to returning normal prose, and describe how the application could use that response.', 'Structured output such as JSON gives the application predictable fields and data types instead of requiring it to interpret arbitrary natural-language prose. For example, a response can contain a numeric score, a summary string, and arrays of strengths and weaknesses. JavaScript can parse that response and directly use the values to update a database, populate an Ext JS DataGrid, display a report, perform calculations, trigger workflow decisions, or send the information to another API. Structured responses improve consistency and reduce fragile text-parsing logic.', 'Award up to 10 points. Full credit should explain that structured data provides predictable machine-readable fields and makes application processing easier and more reliable than parsing prose. The answer should give reasonable examples of how the application can use fields such as storing values, displaying them, filtering, calculating, or making workflow decisions. Partial credit should be awarded if the student recognizes JSON as easier for applications to process but does not clearly explain why.', '10.00', '2' ),
( '11', '2', 'You are building an application that sends many requests to an OpenAI model. Explain what factors you would consider when selecting a model, including quality, latency, capabilities, and cost.', 'Model selection should balance the requirements of the application. Quality includes how accurately and reliably the model performs the task. Latency affects how quickly users receive responses. Capabilities determine whether the model supports the required reasoning, structured outputs, tools, images, documents, or other inputs. Cost depends largely on model pricing and the number of input and output tokens being processed. A developer should select the least expensive and fastest model that still provides acceptable quality and required capabilities, and should test candidate models using representative application data.', 'Award up to 10 points. Full credit should discuss quality, latency, capabilities, and cost. The student should recognize that choosing the most powerful model is not automatically the best solution and that tradeoffs depend on the application. Strong answers should mention testing models against realistic use cases or workloads. Partial credit should be awarded when several correct considerations are discussed but one or more major factors are missing.', '10.00', '3' ),
( '12', '2', 'What is an AI hallucination? Describe at least two techniques you could use in an application to reduce the risk of the model generating unsupported information.', 'An AI hallucination occurs when a model generates information that appears plausible but is unsupported, incorrect, or not grounded in the available information. Risk can be reduced by giving the model reliable source material and explicitly instructing it to use only that material, retrieving relevant information from trusted systems or documents before generating the answer, using tools to obtain factual or current information, requiring citations or evidence, validating structured outputs, asking the model to state when information is unavailable, and applying application-side verification for important results.', 'Award up to 10 points. Full credit requires a reasonable definition of hallucination and at least two valid mitigation techniques. Valid techniques include grounding the response in supplied data, retrieval, tool use, explicit instructions against unsupported assumptions, citations, validation, human review, or application-side verification. Do not require the exact techniques from the reference answer. Partial credit should be awarded for a correct definition with only one mitigation technique or for multiple techniques with an incomplete definition.', '10.00', '4' ),
( '13', '2', 'Your application needs to analyze information contained in documents such as PDFs. Explain how you could provide document information to an OpenAI-powered application and what considerations you would make when deciding how to process those documents.', 'Documents can be provided to an OpenAI-powered application in several ways depending on the API and use case. An application can upload supported documents for the model to process, extract text or other relevant content before sending it, or use a retrieval approach that searches document content and sends only the relevant sections to the model. Important considerations include document size, supported formats, token usage, cost, latency, privacy, whether images or complex layouts matter, how much of the document is relevant, and whether the same documents will be queried repeatedly.', 'Award up to 10 points. Full credit should explain at least one valid way to provide document information, such as uploading the file, extracting its content, or retrieving relevant sections. The answer should discuss multiple processing considerations such as size, tokens, cost, latency, format, privacy, relevance, layout, or repeated usage. Do not require a particular OpenAI API implementation. Partial credit should be given when the general approach is valid but important considerations are missing.', '10.00', '5' ),
( '14', '2', 'Imagine you are building an AI assistant where users can have multi-turn conversations. Explain why conversation context is important and how previous messages can affect the model\'s next response.', 'Conversation context gives the model information about previous messages so that later responses can remain consistent with what the user and assistant have already discussed. A later user message may depend on names, requirements, decisions, or questions introduced earlier. If previous relevant messages are provided to the model, it can use them when interpreting the next request. Without that context, the model may treat the new message as an independent request and may not understand references such as "that option", "change the previous answer", or other earlier information.', 'Award up to 10 points. Full credit should explain that previous messages provide context used to interpret later messages and maintain continuity. The answer should recognize that the model only has access to prior information that the application makes available through the conversation mechanism being used. A concrete example of a later message depending on an earlier one is desirable. Partial credit should be given for recognizing conversational memory or continuity without adequately describing how previous messages influence the next response.', '10.00', '6' ),
( '15', '2', 'An AI assistant needs to look up a customer\'s current order status from your company\'s database. Explain why the model should not simply invent the order status and describe how tools or function calling could be used to solve the problem.', 'The model should not invent an order status because the current status exists in an external company system and may change over time. Instead, the application can expose a controlled tool or function that accepts information such as an order ID. When the model determines that the information is needed, it can request that tool. The application executes the actual database or service lookup, returns the result to the model, and the model uses that result to answer the user. This grounds the response in authoritative current data instead of relying on the model\'s learned knowledge or guesses.', 'Award up to 10 points. Full credit should explain why the model itself cannot be trusted to know a current customer-specific order status and should not fabricate one. The answer should describe the basic tool or function-calling flow: the model requests a tool, application code executes the real lookup, the result is returned, and the model uses it in the response. Partial credit should be awarded when tool use is mentioned but the flow or reason for using it is unclear.', '10.00', '7' ),
( '16', '2', 'An application uses the OpenAI API from a JavaScript web application. Explain where the API key should be stored and why exposing it directly in browser-side JavaScript would be a security problem.', 'The OpenAI API key should be stored on a trusted server-side environment, typically using an environment variable, secret manager, or another secure configuration mechanism. Browser-side JavaScript is delivered to users and can be inspected through developer tools or network activity. If an API key is embedded in frontend code, users or attackers could copy it and make unauthorized API requests, consume the account\'s quota, generate charges, or abuse the service. The browser should normally call the application\'s backend, and the backend should securely make the OpenAI API request.', 'Award up to 10 points. Full credit should state that the API key belongs on the server side and should normally be stored using environment variables, secret storage, or an equivalent secure mechanism. The student should explain that frontend JavaScript is visible to users and that exposing the key enables unauthorized API usage and potentially unwanted costs or abuse. The answer should preferably describe the browser-to-backend-to-OpenAI architecture. Partial credit should be given if the student correctly says not to expose the key but gives limited explanation.', '10.00', '8' ),
( '17', '2', 'You are building an AI system that automatically evaluates open-ended certification exam answers. Describe how you would design the evaluation process so that grading is as consistent, explainable, and reliable as possible.', 'A reliable AI grading system should give the model the exam question, the student answer, a reference answer or expected concepts, a clear scoring rubric, and the maximum score. The rubric should define what constitutes full, partial, and insufficient credit while allowing alternative technically correct wording. The model should return structured results such as score, explanation, matched concepts, missing concepts, and possibly confidence or review status. The application should use consistent model settings and prompts, test the grader against known sample answers, validate scores against the allowed range, and flag ambiguous or low-confidence cases for human review. Important certification systems may also use multiple evaluations, deterministic checks where possible, and periodic comparison against human graders.', 'Award up to 10 points. Full credit should describe a systematic grading process rather than simply asking the model whether an answer is correct. Important concepts include providing the question, student answer, reference answer, and rubric; defining partial credit; requiring structured grading output; maintaining consistent prompts or settings; testing or calibrating the grader; validating results; providing explanations; and using human review for ambiguous cases. The answer does not need every technique listed, but should cover several measures addressing consistency, explainability, and reliability. Partial credit should be awarded to reasonable grading designs that omit some safeguards.', '10.00', '9' ),
( '18', '3', 'Explain the difference between weather and climate. Give an example of each.', 'Weather describes short-term atmospheric conditions in a specific place, such as temperature, rain, wind, or snow on a particular day. Climate describes the long-term average weather patterns of a region over many years. For example, a thunderstorm this afternoon is weather, while a region having hot, dry summers and mild, wet winters is climate.', 'Award up to 10 points. The answer should: distinguish short-term weather from long-term climate; mention atmospheric conditions or patterns; provide a reasonable example of weather; provide a reasonable example of climate. Minor wording differences are acceptable.', '10.00', '1' ),
( '19', '3', 'Why are many of the world\'s largest cities located near rivers, coastlines, or other bodies of water?', 'Cities often develop near water because rivers and coastlines provide transportation routes, access to trade, drinking water, food, fertile land, and opportunities for industry. Historically, waterways made it easier to move people and goods, which encouraged population growth and economic development.', 'Award up to 10 points. Look for several relevant reasons such as transportation, trade, drinking water, food, fertile land, industry, or historical settlement. Full credit does not require every reason, but the answer should clearly explain why access to water supports city growth.', '10.00', '2' ),
( '20', '3', 'Explain why coastal areas often have milder temperatures than inland areas at the same latitude.', 'Large bodies of water heat and cool more slowly than land. During warm periods, nearby water can keep coastal temperatures cooler, while during cold periods it can release stored heat and keep coastal temperatures warmer. This moderates temperature extremes near the coast.', 'Award up to 10 points. The answer should explain that water changes temperature more slowly than land and that this reduces temperature extremes near coastal areas. Partial credit may be given for identifying the moderating effect without fully explaining the mechanism.', '10.00', '3' ),
( '21', '3', 'What is a time zone, and why does the world use different time zones?', 'A time zone is a geographic region that uses the same standard time. Different time zones exist because Earth rotates, causing different parts of the planet to face the Sun at different times. Time zones help local clock time roughly correspond to daylight and nighttime.', 'Award up to 10 points. The answer should define a time zone and connect different time zones to Earth\'s rotation and differences in local daylight. Exact technical terminology is not required.', '10.00', '4' ),
( '22', '3', 'Describe the difference between a country, a continent, and a city. Give one example of each.', 'A country is a political territory with its own government, such as Mexico. A continent is a large geographic landmass, such as North America. A city is a populated urban settlement within a country, such as Mexico City.', 'Award up to 10 points. The answer should correctly distinguish country, continent, and city and provide valid examples of each. Equivalent examples are fully acceptable.', '10.00', '5' ),
( '23', '3', 'Explain how mountains can affect the climate of nearby regions.', 'Mountains can affect temperature and precipitation. Higher elevations are generally cooler. Mountains can also force moist air upward, causing it to cool and produce precipitation on one side, while the opposite side may be much drier because of the rain shadow effect.', 'Award up to 10 points. Look for effects involving elevation and temperature, precipitation, rising air, or rain shadows. Full credit should include a clear explanation of at least two geographic effects, or one effect explained thoroughly.', '10.00', '6' ),
( '24', '3', 'Why are deserts not always hot? Explain what defines a desert.', 'A desert is primarily defined by receiving very little precipitation, not by having high temperatures. Some deserts are hot, while others are cold, such as polar deserts. Low rainfall or snowfall is the main characteristic that defines a desert.', 'Award up to 10 points. The answer should state that deserts are defined mainly by low precipitation and explain that deserts may be either hot or cold. Examples are optional.', '10.00', '7' ),
( '25', '3', 'Explain two ways that geography can influence the economy of a country.', 'Geography can influence an economy through access to natural resources, climate, farmland, transportation routes, ports, tourism, or proximity to other markets. For example, a country with major ports may benefit from international trade, while fertile land may support a strong agricultural sector.', 'Award up to 10 points. The student should identify at least two valid geographic factors and explain how they can affect economic activity. Accept reasonable alternatives beyond those in the reference answer.', '10.00', '8' ),
( '26', '3', 'What is population density, and why can two countries with similar populations have very different population densities?', 'Population density is the number of people living within a given unit of area. Two countries can have similar populations but different densities if one country has much more land area than the other or if their populations are distributed differently.', 'Award up to 10 points. The answer should define population density in relation to population and land area and explain that differences in area or population distribution can produce different densities.', '10.00', '9' ),
( '27', '3', 'A country has fertile farmland, several major rivers, and access to the ocean. Explain how these geographic features could benefit the country.', 'Fertile farmland can support agriculture and food production. Rivers can provide water, transportation, irrigation, and sometimes energy. Ocean access can support ports, fishing, international trade, and transportation. Together, these features can support economic development and population growth.', 'Award up to 10 points. Look for a reasonable explanation of benefits related to farmland, rivers, and ocean access. Full credit should address all three geographic features and connect them to practical benefits.', '10.00', '10' ),
( '28', '4', 'Explain the difference between a solid, a liquid, and a gas in terms of particle movement and shape.', 'In a solid, particles are closely packed and mainly vibrate in fixed positions, so the solid keeps its shape and volume. In a liquid, particles remain close together but can move past one another, so the liquid keeps its volume but takes the shape of its container. In a gas, particles move freely and spread apart, so a gas has neither a fixed shape nor a fixed volume.', 'Award up to 10 points. The answer should correctly describe particle movement and the shape or volume behavior of solids, liquids, and gases. Minor simplifications are acceptable if the main distinctions are correct.', '10.00', '1' ),
( '29', '4', 'What happens to the particles of a liquid when the liquid is heated until it becomes a gas?', 'As the liquid is heated, its particles gain kinetic energy and move faster. Eventually, enough particles have sufficient energy to overcome the attractive forces holding them in the liquid and escape into the gas phase.', 'Award up to 10 points. Look for increased particle energy or movement and an explanation that particles separate or escape into the gas phase. The answer does not need to use the term kinetic energy for full credit if the concept is clear.', '10.00', '2' ),
( '30', '4', 'Explain why plants need sunlight and describe the basic purpose of photosynthesis.', 'Plants use sunlight as an energy source for photosynthesis. During photosynthesis, plants use light energy to convert carbon dioxide and water into sugars that store chemical energy, while oxygen is released as a byproduct.', 'Award up to 10 points. The answer should connect sunlight to energy and explain that photosynthesis allows plants to produce sugars or food from carbon dioxide and water. Mentioning oxygen strengthens the answer but is not required for full credit if the core process is correct.', '10.00', '3' ),
( '31', '4', 'What is gravity, and how does it affect objects on Earth?', 'Gravity is the force of attraction between objects that have mass. Earth\'s gravity pulls objects toward its center, giving objects weight and causing unsupported objects to fall toward the ground.', 'Award up to 10 points. The answer should identify gravity as an attractive force associated with mass and describe at least one effect on Earth, such as falling objects, weight, or objects being held near the surface.', '10.00', '4' ),
( '32', '4', 'Explain the difference between mass and weight.', 'Mass is the amount of matter in an object and generally remains constant regardless of location. Weight is the force caused by gravity acting on that mass, so weight can change depending on the strength of gravity.', 'Award up to 10 points. The answer should correctly distinguish mass from gravitational force or weight and explain that mass stays essentially constant while weight can change with gravity.', '10.00', '5' ),
( '33', '4', 'Why does ice float on liquid water?', 'Ice floats because solid water is less dense than liquid water. When water freezes, its molecules form a structure that keeps them farther apart than in liquid water, reducing the density of the solid.', 'Award up to 10 points. Full credit requires identifying lower density as the reason ice floats. Additional explanation of molecular spacing is desirable but not required for full credit.', '10.00', '6' ),
( '34', '4', 'Explain the difference between renewable and nonrenewable energy sources. Give one example of each.', 'Renewable energy sources are naturally replenished on a human timescale, such as solar, wind, or hydroelectric energy. Nonrenewable energy sources exist in limited quantities or take extremely long periods to form, such as coal, oil, or natural gas.', 'Award up to 10 points. The answer should clearly distinguish renewable from nonrenewable sources and give one correct example of each.', '10.00', '7' ),
( '35', '4', 'Describe one important role that bacteria can play in nature or in human life.', 'Bacteria can play many beneficial roles. They can help decompose dead material, recycle nutrients in ecosystems, assist digestion, produce certain foods, or support other biological processes. Some bacteria can also cause disease, but bacteria are not universally harmful.', 'Award up to 10 points. Accept any scientifically reasonable bacterial role with an explanation. Full credit may be earned using beneficial or harmful examples as long as the role is accurately described.', '10.00', '8' ),
( '36', '4', 'Why do scientists repeat experiments and compare results?', 'Scientists repeat experiments to determine whether results are consistent and reproducible. Repetition helps reduce the impact of random errors, identify unusual results, and provide stronger evidence for a conclusion.', 'Award up to 10 points. The answer should connect repetition with reliability, consistency, reproducibility, reducing error, or strengthening evidence. Exact terminology is not necessary.', '10.00', '9' ),
( '37', '4', 'A metal spoon and a wooden spoon have been sitting in the same room for several hours. The metal spoon feels colder when touched. Explain why.', 'The two spoons may actually be at approximately the same room temperature. Metal feels colder because it conducts heat away from the hand much faster than wood. The faster transfer of heat from the skin creates the sensation that the metal is colder.', 'Award up to 10 points. Full credit should explain that the objects can be at the same temperature and that metal conducts heat more effectively than wood, causing faster heat transfer from the hand.', '10.00', '10' ),
( '38', '5', 'What is the purpose of defining project scope before beginning a project?', 'Project scope defines what the project will and will not include. It establishes expected deliverables, boundaries, and objectives so that the team and stakeholders share a common understanding of the work. Clear scope also helps control unnecessary changes and supports planning for time, cost, and resources.', 'Award up to 10 points. Look for concepts such as defining deliverables, boundaries, objectives, expectations, preventing uncontrolled changes, or supporting planning. Full credit does not require every concept.', '10.00', '1' ),
( '39', '5', 'Explain the difference between a project milestone and a project task.', 'A task is a specific piece of work that must be completed and normally requires time and resources. A milestone is a significant checkpoint or event in the project, such as completing a major phase or receiving approval, and typically represents progress rather than a duration of work.', 'Award up to 10 points. The answer should distinguish an activity or work item from a significant checkpoint or event. Examples may be used but are not required.', '10.00', '2' ),
( '40', '5', 'Why is it important to identify project risks before they become problems?', 'Identifying risks early allows the project team to evaluate their likelihood and impact and prepare responses before they occur. This can reduce delays, costs, quality problems, and disruptions and can improve the team\'s ability to respond effectively.', 'Award up to 10 points. Look for early identification, assessment of likelihood or impact, preparation or mitigation, and reduction of negative project effects. Equivalent reasoning is acceptable.', '10.00', '3' ),
( '41', '5', 'A critical project task is running two weeks behind schedule. As the project manager, explain what you would do next.', 'The project manager should first determine the cause and impact of the delay, especially whether it affects dependent tasks or the final deadline. The manager should work with the team to identify recovery options, such as adjusting priorities, adding resources, changing sequencing, or revising the schedule. Relevant stakeholders should be informed, and the project plan should be updated if necessary.', 'Award up to 10 points based on quality of reasoning. Strong answers should include assessing the cause and impact, identifying corrective actions, reviewing dependencies or schedule effects, communicating with stakeholders, and updating the plan. Do not require the exact recovery actions in the reference answer.', '10.00', '4' ),
( '42', '5', 'What is a stakeholder in a project, and why should stakeholders be identified early?', 'A stakeholder is a person, group, or organization that can affect the project, is affected by the project, or has an interest in its outcome. Identifying stakeholders early helps the project team understand expectations, communication needs, decision-making roles, influence, and potential concerns.', 'Award up to 10 points. The answer should define stakeholder broadly and explain why early identification supports communication, expectations, decisions, engagement, or risk management.', '10.00', '5' ),
( '43', '5', 'Explain why regular project status meetings can be useful. Also describe one problem that can occur if they are poorly managed.', 'Status meetings can help the team share progress, identify blockers, coordinate work, make decisions, and communicate changes. If poorly managed, they can become too long, repetitive, unfocused, or consume time without producing decisions or actions.', 'Award up to 10 points. The answer should identify at least one meaningful benefit of status meetings and one reasonable disadvantage or problem associated with poorly managed meetings.', '10.00', '6' ),
( '44', '5', 'A client requests a major new feature halfway through a project. Explain how the project manager should handle the request.', 'The project manager should document and clarify the requested change, evaluate its effect on scope, schedule, cost, resources, risks, and quality, and present the impact to the appropriate stakeholders. The change should go through the project\'s approval or change-control process before being added to the committed scope.', 'Award up to 10 points. Strong answers should avoid simply accepting the request immediately. Look for clarification, impact analysis, stakeholder discussion, approval or change control, and updating project plans if approved.', '10.00', '7' ),
( '45', '5', 'Why is communication important in project management? Give an example of information that should be communicated to the project team.', 'Communication helps ensure that team members and stakeholders understand goals, responsibilities, progress, changes, risks, and decisions. Examples of important information include deadlines, task assignments, scope changes, blockers, risks, priorities, or project status.', 'Award up to 10 points. The answer should explain how communication supports alignment or coordination and provide at least one reasonable example of project information that should be shared.', '10.00', '8' ),
( '46', '5', 'Two important tasks require the same team member at the same time. How could a project manager address this resource conflict?', 'The project manager should evaluate the priorities, dependencies, deadlines, and available alternatives. Possible solutions include rescheduling one task, changing task sequencing, assigning another qualified person, adjusting priorities, negotiating deadlines, or adding resources if appropriate. The decision should consider the overall project impact.', 'Award up to 10 points based on reasoning. Accept different solutions if they are practical. Strong answers should recognize the conflict, evaluate project priorities or dependencies, and propose a realistic resolution rather than simply ignoring one of the tasks.', '10.00', '9' ),
( '47', '5', 'At the end of a project, why is it useful to review what went well and what could have been improved?', 'A project review or lessons-learned activity helps the team identify successful practices, mistakes, problems, and opportunities for improvement. Recording these lessons can help future projects repeat effective practices and avoid similar problems.', 'Award up to 10 points. Look for learning, continuous improvement, preserving successful practices, avoiding repeated mistakes, or helping future projects. The answer does not need to use the term lessons learned.', '10.00', '10' );
INSERT INTO `student_answers`(`id`,`attempt_id`,`question_id`,`answer_text`,`score`,`percentage`,`feedback`,`strengths`,`weaknesses`,`confidence`,`grading_status`,`ai_response`,`graded_at`) VALUES 
( '1', '1', '1', 'var is the old way to create variables. let is better because it can change, and const is for values that should not be reassigned. let and const are block scoped while var is function scoped.', '6.00', NULL, 'Good attempt at explaining the differences, but lacked depth regarding reassignment and redeclaration nuances. Try to mention the preferred cases for each.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '2', '1', '2', 'async and await make JavaScript wait until everything in the program is finished before continuing.', '3.00', NULL, 'You identified asynchronous behavior but didn’t clarify how Promises work or give a concrete example. More depth is needed.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '3', '1', '3', 'Arrays are for lists of values and objects are for properties identified by names. I would use an array for employees and an object for one employee.', '7.00', NULL, 'You explained the basic distinctions between objects and arrays well but could provide stronger examples and more detail about use cases.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '4', '1', '4', 'Scope means where a variable can be accessed. Global variables can be accessed everywhere, function scoped variables only inside a function, and block scoped variables inside blocks such as if statements.', '9.00', NULL, 'Great explanation of variable scope with clear definitions. Just a minor detail could enhance your response.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '5', '1', '5', 'An Ext JS component is something displayed on the screen, like a grid, button, panel, form, or window. Applications are built by combining components.', '8.00', NULL, 'You provided a solid overview of Ext JS components and their combinations. A bit more detail could have added further clarity.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '6', '1', '6', 'A DataGrid is basically a spreadsheet that stores all of the data directly inside each cell.', '2.00', NULL, 'Your description of the DataGrid was very limited. It’s crucial to explain the data flow and how it relates to the Store.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '7', '1', '7', 'Models describe records and stores contain collections of those records. Components such as grids bind to stores to display the data.', '7.00', NULL, 'You correctly identified the roles of Models and Stores, but could elaborate on how they interact more effectively.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '8', '1', '8', 'Events happen when the user interacts with components. You can add listeners for events such as click or selectionchange and execute code when they happen.', '8.00', NULL, 'Solid explanation of events in Ext JS with examples. Just make sure to emphasize how event handlers access data.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '9', '2', '1', 'var is function scoped and may be redeclared. let and const are block scoped. let allows reassignment while const prevents reassignment of the binding. I generally prefer const unless reassignment is required.', '7.00', NULL, 'Good explanation of variable scopes, but missing details on redeclaration and the nuances of const.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '10', '2', '2', 'An async function returns a Promise. await pauses execution inside that async function until the awaited Promise settles. This is useful for API requests, database calls, or other asynchronous operations.', '9.00', NULL, 'Well done! You accurately explained async and await behavior with a clear context for asynchronous programming.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '11', '2', '3', 'An array is an ordered collection indexed numerically. An object stores key-value properties. Arrays are appropriate for collections and objects for structured entities.', '8.00', NULL, 'Nice distinction between arrays and objects, but missing some deeper explanations.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '12', '2', '4', 'JavaScript has global, function, and block scope. var follows function scope while let and const follow block scope. A variable is only accessible within the scope in which it is declared and nested scopes.', '9.00', NULL, 'Strong understanding of scope!', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '13', '2', '5', 'Ext JS components are reusable UI building blocks derived from the component system. Examples include panels, grids, forms, windows, buttons, and fields. They can be nested and configured to construct an application interface.', '9.00', NULL, 'Great explanation of Ext JS components and their use.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '14', '2', '6', 'An Ext JS DataGrid displays records from a Store. The Store contains Models or records, and the grid columns map record fields to visual columns.', '8.00', NULL, 'You understand the DataGrid concept well, but details on the data flow could have been clearer.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '15', '2', '7', 'A Model defines fields and behavior for a record. A Store manages collections of model records, including loading, sorting, filtering, and syncing.', '8.00', NULL, 'Good explanation, but you need to articulate the relationship and interaction between Models and Stores further.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '16', '2', '8', 'Ext JS components fire events. Controllers or components can attach listeners to those events. For example, a grid selectionchange handler can respond when a row is selected.', '9.00', NULL, 'Solid understanding of event handling in Ext JS.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '17', '3', '1', 'let and const are newer than var. const cannot be reassigned and let can. var behaves differently with scope and is usually avoided in modern JavaScript.', '7.00', NULL, 'Your answer identifies key differences but lacks detail on scope and use cases for each declaration type.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '18', '3', '2', 'async and await provide cleaner syntax for working with Promises. await lets asynchronous operations appear sequential without blocking the entire browser.', '6.00', NULL, 'You recognize async and await but haven\'t fully explained their roles with Promises.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '19', '3', '3', 'Arrays are ordered collections while objects use named properties. An array is useful for a set of similar records and an object for representing one structured thing.', '8.00', NULL, 'Good distinction made between objects and arrays with examples, but could use more depth on use cases.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '20', '3', '4', 'Scope determines where a variable exists. Global is available broadly, function scope stays inside a function, and block scope applies inside braces for let and const.', '9.00', NULL, 'Your explanation of variable scope is well stated and covers the key differences clearly.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '21', '3', '5', 'A component is a reusable Ext JS UI element such as a panel, grid, form, button, or window.', '7.00', NULL, 'You defined components well but need to explain how they work together in an application context.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '22', '3', '6', 'The grid displays records provided by a Store. Columns specify which fields of each record should appear and can also control rendering and behavior.', '8.00', NULL, 'Described the grid\'s functionality well but should expand on the data flow aspect.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '23', '3', '7', 'Models define what a record looks like. Stores load and hold groups of those records and are often connected to grids or other data-aware components.', '8.00', NULL, 'You accurately detail the roles of Models and Stores, but could clarify their interaction more.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '24', '3', '8', 'Events let your application react to actions. You can listen for a grid row selection or button click and run a handler.', '8.00', NULL, 'You covered the event handling concept well but could provide more concrete examples.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '25', '4', '1', 'var, let and const all create variables. let and const have block scope, but var has function scope. const should be used when the variable will not be reassigned.', '6.00', NULL, 'You correctly identified the scope differences between let and const versus var but missed explaining const\'s prevention of reassignment and failed to include when to use each variable declaration effectively.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '26', '4', '2', 'async means a function can perform asynchronous work. await waits for a Promise result inside the async function. It could be used when loading data from a server.', '7.00', NULL, 'You understood the basic concept of async and await, but your example of using async was very brief. Including details on the Promise aspect would strengthen your answer.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '27', '4', '3', 'Objects use names for their values and arrays use numbered positions. Arrays are good for lists and objects are good for records with fields.', '7.00', NULL, 'You\'ve correctly identified basic characteristics of objects and arrays but didn\'t provide much detail about use cases or the specific behaviors of arrays as objects in JavaScript.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '28', '4', '4', 'Scope is the part of the application that can see a variable. A global variable can be seen by many functions, while function and block variables have more limited visibility.', '8.00', NULL, 'Your answer provided a good definition of scope and addressed global, function, and block scopes. However, it could improve by mentioning var, let, and const explicitly.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '29', '4', '5', 'Ext JS components are UI elements. You configure them and combine them inside containers to build screens.', '6.00', NULL, 'You described Ext JS components\' basic function well but didn’t provide enough examples, and your explanation could be clearer regarding how they are used in applications.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '30', '4', '6', 'A DataGrid is used to show tabular information. It normally reads records from a Store and uses configured columns to display fields.', '8.00', NULL, 'Your answer effectively conveyed the function of a DataGrid and its relation to the Store, although mentioning the model would further clarify the flow of data.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '31', '4', '7', 'A Model represents one item of data and a Store represents many items.', '5.00', NULL, 'You\'ve noted the general representations of a Model and Store, but your explanation lacks depth regarding their roles, especially how they interact when data changes.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '32', '4', '8', 'Components can fire events such as click and select. You attach a listener and put the desired behavior in the handler.', '8.00', NULL, 'Your explanation of how events work in Ext JS is generally sound, but including specific examples of events and handlers could strengthen your response.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '33', '5', '1', 'let should always be used because const prevents objects from changing at all. var and const are basically obsolete.', '3.00', NULL, 'Your answer mentions that \'const prevents objects from changing,\' which is not entirely accurate. While it cannot be reassigned, objects can still be mutated. You also didn\'t discuss the differences in scope and appropriate usage for each keyword well.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '34', '5', '2', 'async and await are used to work with asynchronous operations such as HTTP requests. await waits for a Promise inside an async function.', '6.00', NULL, 'You correctly defined async and await but did not explain how they work with Promises or provide a detailed example of asynchronous programming. More information would improve your answer significantly.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '35', '5', '3', 'An object stores key-value pairs. Arrays are also objects but are designed for ordered lists. I would use an array when order or iteration over a collection matters.', '7.00', NULL, 'Your answer clearly identifies the key characteristics of objects and arrays, as well as appropriate use cases. However, you did not expand on how arrays are technically objects in JavaScript, which could have enhanced your response.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '36', '5', '4', 'Global variables are declared anywhere, function variables are declared with var, and block variables are declared only with const.', '4.00', NULL, 'Your explanation of global, function, and block scope is incomplete. It\'s crucial to clearly articulate that block scope is not limited to just \'const\' but also includes variables declared with \'let\'.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '37', '5', '5', 'A component is a reusable UI object in Ext JS. Panels, grids, forms and windows are examples.', '6.00', NULL, 'You provided a basic understanding of components but did not elaborate on how they are configured and used to build an Ext JS application. Your answer needs more detail to demonstrate full understanding.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '38', '5', '6', 'The DataGrid displays records in rows and fields in columns. Usually a Store retrieves the records and the grid is configured with columns that correspond to model fields.', '7.00', NULL, 'Your answer correctly outlines the role of the DataGrid regarding rows and columns and touches upon Store functionality, but a deeper understanding of the data flow process and how the Store manages Model instances would enhance your explanation.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '39', '5', '7', 'A Model defines the data fields of one record and a Store contains multiple records, handling things such as loading and filtering.', '6.00', NULL, 'You mention the roles of Models and Stores well, but fail to explain how they work together in detail. Mentioning how data displayed in components reflects changes would strengthen your answer.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '40', '5', '8', 'Events notify code that something occurred, such as a button click or grid selection. A listener responds to that event.', '8.00', NULL, 'You clearly explained the concept of events in Ext JS and provided a simple example of how to respond to them. Expanding on how the event handlers access relevant information could make your answer even stronger.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '41', '6', '1', 'const means constant and should be used for any value that never changes. let is for variables that change. var is older and has function scope instead of block scope.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '42', '6', '2', 'await tells the CPU to stop running JavaScript until the request completes.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '43', '6', '3', 'Arrays are objects with numeric indexes. Objects usually use named properties.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '44', '6', '4', 'Scope controls where identifiers can be accessed. Global scope is broad, function scope belongs to the function, and block scope belongs to a block.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '45', '6', '5', 'Ext JS applications are composed of components. A button, panel, window, grid and form are components.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '46', '6', '6', 'A DataGrid visualizes structured records. A Store provides the records and the columns determine how record fields are shown.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '47', '6', '7', 'Models define fields and Stores manage records.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '48', '6', '8', 'Events allow components to notify other code when something happens. Event handlers can respond to clicks and selections.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '49', '7', '1', 'var is global, let is local, and const is private.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '50', '7', '2', 'async and await are mostly a nicer way to use Promises. await can pause an async function while an API request completes.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '51', '7', '3', 'An array is a numbered list. An object uses named keys.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '52', '7', '4', 'Scope means whether JavaScript remembers the variable after the page loads.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '53', '7', '5', 'A component is anything the user sees, such as a grid or button, and components can be nested to create an interface.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '54', '7', '6', 'The grid takes data from a Store and displays each record as a row. The columns decide which fields are shown.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '55', '7', '7', 'A Store is where application data is held. Models describe the data structure.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '56', '7', '8', 'You can listen to an event like click and call a function when it happens.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '57', '8', '1', 'var is function scoped and supports redeclaration. let is block scoped and allows reassignment. const is block scoped and does not allow reassignment of the variable binding, although referenced objects may still be mutated.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '58', '8', '2', 'async functions return Promises. await suspends execution of that async function until the Promise settles without blocking the JavaScript event loop.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '59', '8', '3', 'Arrays are specialized objects optimized semantically for ordered collections and numeric indexing. Objects are more appropriate for named properties representing entities or dictionaries.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '60', '8', '4', 'Lexical scope determines where variables can be referenced. Global scope is broadly visible, function scope limits variables to a function, and block scope limits let and const to the surrounding block.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '61', '8', '5', 'Ext JS components are configurable, lifecycle-managed UI classes. Common examples include Grid, Panel, Form, Window, Button and various fields. Applications compose these components into containers and views.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '62', '8', '6', 'A grid binds to a Store containing records. Models define record fields, the Store loads and manages those records, and grid column definitions map fields to cells.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '63', '8', '7', 'Models define fields, validation, associations and record behavior. Stores manage collections and support loading, filtering, sorting, grouping and synchronization.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '64', '8', '8', 'Ext JS uses an event-driven component model. Components publish events and listeners or controller handlers react to events such as selectionchange, click, change or store load.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '65', '9', '1', 'let and const are block scoped. var is function scoped. I use const by default, let when reassignment is needed, and rarely use var in new code.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '66', '9', '2', 'async and await help you deal with things that take time, like server requests, while keeping the code readable.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '67', '9', '3', 'An array is a list, while an object describes something using properties.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '68', '9', '4', 'Scope defines where a variable can be used. Global scope is everywhere, function scope is inside a function, and block scope is inside a block.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '69', '9', '5', 'An Ext JS component is a reusable part of the UI. A grid, button, form and panel are examples.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '70', '9', '6', 'The DataGrid shows data as rows and columns. A Store supplies the records and the grid columns show selected fields.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '71', '9', '7', 'Models describe the records, and Stores hold them and provide them to the UI.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '72', '9', '8', 'Events let the application respond to user actions by registering handlers.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '73', '10', '1', 'const cannot be changed, let can be changed, and var is the same as let but older.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '74', '10', '2', 'await is used inside async functions to wait for asynchronous results such as a Promise from a network request.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '75', '10', '3', 'Arrays are ordered lists and objects contain named properties.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '76', '10', '4', 'Global variables can be accessed from everywhere. Function variables are scoped to functions and block variables to blocks.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '77', '10', '5', 'Ext JS components are interface widgets such as grids, forms, panels and windows.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '78', '10', '6', 'The grid loads data from the database and automatically knows what fields to display.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '79', '10', '7', 'Models hold individual data and Stores hold collections of data.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '80', '10', '8', 'Listeners are used to react to events such as clicking a button.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '81', '11', '1', 'var declarations are function scoped and hoisted. let and const are block scoped and have temporal dead zones. const prevents reassignment but does not make referenced objects immutable.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '82', '11', '2', 'async marks a function as Promise-returning. await asynchronously waits for settlement of a Promise and resumes the function afterward. This is useful for network I/O, file operations through APIs, and other Promise-based operations.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '83', '11', '3', 'Arrays provide ordered integer-indexed collections with array-specific methods. Objects use named properties and are appropriate for structured records or mappings.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '84', '11', '4', 'JavaScript uses lexical scoping. Global bindings live in global scope, var has function scope, and let/const have block scope. Inner scopes may reference bindings in outer scopes.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '85', '11', '5', 'An Ext JS component is an instance of the framework component hierarchy with configuration, rendering, lifecycle and events. Applications compose components and containers into views.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '86', '11', '6', 'A grid presents records from a bound Store. The Store obtains and manages records, often instances of a Model, and column configurations determine field presentation.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '87', '11', '7', 'A Model defines the schema and behavior for records. A Store owns collections of records and handles querying, filtering, sorting, loading and synchronization.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '88', '11', '8', 'Components and data classes fire events through the framework event system. Listeners, controllers or view controllers can bind handlers to events such as click or selectionchange.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '89', '12', '1', 'let is for numbers, const is for strings, and var can hold anything.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '90', '12', '2', 'async and await make requests happen in the background so the UI does not freeze while you are waiting for something such as an API response.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '91', '12', '3', 'Arrays contain multiple things and objects normally contain one thing with properties.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '92', '12', '4', 'Scope is where a variable is allowed to be used.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '93', '12', '5', 'Components are things like buttons, windows and grids that you place in the app.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '94', '12', '6', 'A grid makes database tables visible in the browser.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '95', '12', '7', 'The Store gets the data and the Model says what the fields are.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '96', '12', '8', 'Events are actions such as click and you can run code when they happen.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '97', '13', '1', 'var has function scope while let and const have block scope. let allows reassignment and const does not. In most cases modern code prefers const or let.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '98', '13', '2', 'async and await simplify Promise-based asynchronous code. A server request is a common use because you can await the response.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '99', '13', '3', 'Arrays are ordered and usually represent collections. Objects use keys and are useful for entities with named fields.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '100', '13', '4', 'Scope determines visibility. Global is visible generally, function scope is restricted to a function, and block scope is restricted to a block.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '101', '13', '5', 'Ext JS components are reusable UI elements, including grids, panels, forms, windows and buttons.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '102', '13', '6', 'A grid uses a Store to get records and columns to determine what fields appear.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '103', '13', '7', 'A Model defines a record while a Store holds many records. Stores can also load and filter those records.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '104', '13', '8', 'Events are notifications from components. A listener can respond to a click or selection and execute application logic.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '105', '14', '1', 'const is permanent, let lasts until the function ends, and var lasts until the browser closes.', '2.00', NULL, 'This answer does not accurately describe the distinctions between let, const, and var. It lacks detail on scope and reassignments.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '106', '14', '2', 'async and await are used when code has to wait for something, especially a server response.', '4.00', NULL, 'This answer presents a basic understanding of async, but lacks an explanation of Promises or an example of a situation requiring async programming.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '107', '14', '3', 'Arrays are indexed with numbers and objects usually use keys.', '3.00', NULL, 'The answer correctly identifies key differences but lacks examples and use cases.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '108', '14', '4', 'Global scope is for variables outside functions. Function scope is inside a function. Block scope exists inside braces.', '6.00', NULL, 'The answer provides a basic understanding of scope but misses detail on how it impacts variable accessibility.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '109', '14', '5', 'An Ext JS component is a reusable visual or interactive element such as a panel, grid, button, field or window.', '7.00', NULL, 'This answer provides a good definition of an Ext JS component and several examples, but lacks detail on how they\'re used in applications.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
