INSERT INTO `student_answers`(`id`,`attempt_id`,`question_id`,`answer_text`,`score`,`percentage`,`feedback`,`strengths`,`weaknesses`,`confidence`,`grading_status`,`ai_response`,`graded_at`) VALUES 
( '296', '30', '28', 'A solid is something you can touch, liquid is something you drink, and gas is air.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '297', '30', '29', 'The particles disappear when the liquid becomes a gas.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '298', '30', '30', 'Plants eat sunlight.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '299', '30', '31', 'Gravity is the atmosphere pushing everything down.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '300', '30', '32', 'Mass and weight are two words for the same thing.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '301', '30', '33', 'Ice floats because frozen things always float.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '302', '30', '34', 'Renewable means electricity and nonrenewable means fuel.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '303', '30', '35', 'All bacteria are dangerous and should be removed.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '304', '30', '36', 'Scientists repeat experiments because they need more work to do.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '305', '30', '37', 'The metal spoon feels colder because metal creates cold.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '311', '31', '38', 'Defining scope establishes the project objectives, deliverables, boundaries, and exclusions. It gives the team and stakeholders a shared understanding of what will be delivered and provides a baseline for estimating schedule, cost, and resources. It also helps prevent uncontrolled scope creep.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '312', '31', '39', 'A task is a specific activity that requires work, time, and usually resources. A milestone is a significant checkpoint or achievement in the project, such as completion of a phase or formal customer approval, and normally has no duration of its own.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '313', '31', '40', 'Identifying risks early allows the team to evaluate probability and impact and prepare mitigation or contingency plans before the issue occurs. This can reduce schedule delays, unexpected costs, quality problems, and disruption.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '314', '31', '41', 'I would first identify why the critical task is late and determine how the delay affects dependencies and the final delivery date. I would then evaluate recovery options such as resequencing work, reallocating resources, reducing noncritical work, or adjusting dates. I would communicate the impact and proposed plan to the appropriate stakeholders and update the schedule.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '315', '31', '42', 'A stakeholder is any person, group, or organization that can influence the project, is affected by it, or has an interest in its outcome. Identifying them early helps determine expectations, decision authority, communication needs, influence, and possible risks.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '316', '31', '43', 'Regular status meetings allow the team to coordinate activities, report progress, identify blockers, discuss risks, and make decisions. Poorly managed meetings can become long and repetitive without clear decisions, owners, or action items.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '317', '31', '44', 'I would document and clarify the requested feature and perform an impact analysis covering scope, schedule, cost, resources, risks, and quality. I would present those impacts to the decision makers. The feature should only enter the committed project scope after going through the agreed change-control and approval process.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '318', '31', '45', 'Communication keeps stakeholders and team members aligned on objectives, responsibilities, risks, progress, and decisions. For example, if a deadline changes, affected team members should know the new date, why it changed, and how it affects their work.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '319', '31', '46', 'I would evaluate the priorities, dependencies, and deadlines for both tasks. Depending on the impact, I could resequence one task, assign another qualified resource, negotiate a deadline, or add capacity. The decision should optimize the overall project rather than simply favoring whichever task was requested first.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '320', '31', '47', 'A lessons-learned review allows the team to identify what worked, what failed, and why. Documenting those findings helps future teams repeat successful practices, avoid recurring mistakes, and improve planning and execution.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '326', '32', '38', 'Project scope explains what the project is expected to deliver and what work is included. It keeps everyone aligned and helps prevent people from continually adding new requirements.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '327', '32', '39', 'A task is work that somebody performs over a period of time. A milestone represents an important point in the project, such as finishing a phase.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '328', '32', '40', 'If risks are found early, the team can decide how likely they are, understand their impact, and create plans to reduce the damage if they happen.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '329', '32', '41', 'I would determine what caused the delay and whether other tasks depend on this one. Then I would look for ways to recover time, possibly by assigning more resources or changing priorities. I would also inform stakeholders if the final schedule might be affected.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '330', '32', '42', 'A stakeholder is someone who has an interest in the project or will be affected by it. Finding stakeholders early allows the project manager to understand what they expect and how they need to be communicated with.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '331', '32', '43', 'Status meetings help everyone understand progress and discuss blockers. They become a problem if there is no agenda and people spend a lot of time discussing things that are not important.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '332', '32', '44', 'The project manager should not immediately promise the feature. The request should be analyzed to determine the extra time, cost, and resources it requires and then sent for approval.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '333', '32', '45', 'Good communication keeps everyone working toward the same goals. Project members should be told about important information such as deadline changes, priorities, and risks.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '334', '32', '46', 'The project manager should determine which task has higher priority and whether one can be moved. Another team member could also be assigned if someone qualified is available.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '335', '32', '47', 'Reviewing the project helps the team learn from mistakes and identify practices that worked well so future projects can improve.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '341', '33', '38', 'Scope tells the team what needs to be completed in the project and helps make sure people do not add unrelated work.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '342', '33', '39', 'A task is an activity people must complete. A milestone is an important point that shows progress.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '343', '33', '40', 'It is better to know about possible problems before they happen because the team can prepare for them.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '344', '33', '41', 'I would ask the team why the task is late and try to determine if we can finish it faster. I would change the schedule if necessary and tell the client about important delays.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '345', '33', '42', 'Stakeholders are people involved in or affected by the project. They should be identified so the project manager knows who needs information.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '346', '33', '43', 'Meetings allow people to share project progress and problems. Too many meetings can waste time.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '347', '33', '44', 'I would determine how much extra work the new feature requires before agreeing to it. If it affects the deadline or price, I would discuss that with the client.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '348', '33', '45', 'Communication makes sure people know what they are supposed to do. For example, everyone should know their deadlines.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '349', '33', '46', 'I would decide which task is more important and move the other one to another time if possible.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '350', '33', '47', 'A final review can help the team find mistakes so they do not repeat them on another project.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '356', '34', '38', 'Scope is a list of things that should be done during the project.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '357', '34', '39', 'Tasks are things people work on and milestones are important dates.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '358', '34', '40', 'Risks should be identified so the project manager knows that something bad could happen.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '359', '34', '41', 'I would tell the person responsible to work faster and ask them when they can finish.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '360', '34', '42', 'A stakeholder is somebody interested in the project, usually the customer.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '361', '34', '43', 'Meetings are useful because everybody can talk about the project. They can become too long.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '362', '34', '44', 'I would ask the development team if they can add the feature and tell the client how long it will take.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '363', '34', '45', 'Communication is important because people need to know what is happening.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '364', '34', '46', 'I would have the employee finish the most urgent task first.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '365', '34', '47', 'It helps determine if the project was successful or not.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '371', '35', '38', 'Scope means how large the project is.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '372', '35', '39', 'A milestone is a really difficult task.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '373', '35', '40', 'Risks are problems that already happened.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '374', '35', '41', 'I would change the deadline without telling anyone so the team has more time.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '375', '35', '42', 'Stakeholders are the people who own shares of the company.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '376', '35', '43', 'Project meetings are mostly useful so managers can make sure everybody is working.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '377', '35', '44', 'If the customer asks for a feature, I would add it because keeping the customer happy is the most important thing.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '378', '35', '45', 'Communication means sending emails to everyone.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '379', '35', '46', 'The employee should work on both tasks at the same time.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '380', '35', '47', 'There is no real need to review a project after it is finished because the work has already been delivered.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '386', '36', '9', 'System or developer instructions establish the behavior, constraints, role, and rules the model should follow throughout the interaction. A user message contains the request or data from the end user. Higher-level instructions should guide how the model interprets and responds to user requests.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '387', '36', '10', 'An OpenAI API key is a secret credential that can authorize requests and potentially incur charges. If it is placed in JavaScript running in the browser, users can inspect the source code or network traffic and obtain it. The key should normally be stored securely on a backend server, usually through an environment variable or secret-management service. The frontend should call the application backend, and the backend should call OpenAI.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '388', '36', '11', 'Tokens are units used by language models to process text. A token can represent a whole word, part of a word, punctuation, or other text fragments. Token usage matters because models have context limits and API costs are generally related to the number of input and output tokens processed. Developers should avoid unnecessarily large prompts and responses.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '389', '36', '12', 'Normal text output gives the model flexibility to produce human-readable prose, but parsing that output programmatically can be unreliable. Structured JSON output provides predictable fields and data types that an application can validate and consume. For application workflows, a defined schema is preferable when the response needs to be processed by code.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '390', '36', '13', 'My application would collect the required input and send it to my backend. The backend would validate the data, construct the OpenAI request including instructions and user content, authenticate using the API key, and call the API. After receiving the response, the backend would validate and parse it, handle errors, optionally save relevant results, and return only the required information to the frontend.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '391', '36', '14', 'Temperature influences how deterministic or varied model output is. Lower values generally favor more consistent and predictable responses, while higher values allow more variation. I would prefer a low temperature for tasks such as extraction, classification, grading, or generation of structured application data where consistency is more important than creativity.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '392', '36', '15', 'AI output should be treated as untrusted application input. A model can misunderstand instructions, omit required fields, produce unexpected values, or return information in an incorrect format. The application should validate schemas, data types, ranges, required fields, and business rules before saving the result or using it to trigger another operation.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '393', '36', '16', 'Files can provide source information that would be inconvenient or impossible to include manually as plain prompt text. An application can upload supported files and reference them when asking the model to analyze their contents. Examples include resumes, job descriptions, reports, or other documents. The application should still control which files are accepted and should manage them according to security and privacy requirements.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '394', '36', '17', 'The application should catch API and network errors instead of assuming every request succeeds. Timeouts should be configured appropriately, transient failures may be retried with controlled backoff, and rate-limit responses should be handled without repeatedly overwhelming the API. Errors should be logged appropriately and the user should receive a useful message. Retries should also avoid accidentally repeating operations with unwanted side effects.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '401', '37', '9', 'System or developer instructions tell the AI how it should behave and what rules it should follow. The user message contains the actual question or request. The instructions provide the context for how the user request should be handled.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '402', '37', '10', 'API keys should not be included in browser JavaScript because anyone using developer tools could find them. The frontend should communicate with a backend server and the backend should keep the API key in an environment variable and make the OpenAI request.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '403', '37', '11', 'Tokens are pieces of text processed by the model. They matter because the model can only process a certain amount of context and because more tokens can increase API cost.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '404', '37', '12', 'Normal text is useful when the result is mainly for a person to read. JSON is more useful when software needs to consume the response because the application can access specific properties instead of trying to interpret paragraphs of text.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '405', '37', '13', 'The frontend would send the user information to my server. The server would create the prompt and call OpenAI using the API key. When the response arrives I would parse it, check that the expected information is present, and return the data to the frontend.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '406', '37', '14', 'Temperature changes how much variation appears in answers. I would use a low temperature for predictable things like grading or generating JSON and a higher value for more creative tasks.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '407', '37', '15', 'The output should be validated because AI responses are not guaranteed to always have exactly what the application expects. I would make sure required JSON fields exist and that numbers and other values are valid before saving them.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '408', '37', '16', 'Files can be uploaded so the model can work with documents such as resumes or reports instead of requiring the user to manually copy all of their contents into a prompt.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '409', '37', '17', 'The backend should catch errors and return an understandable error message. It should configure a timeout and can retry temporary failures. Rate-limit errors should be handled by waiting before sending more requests.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '416', '38', '9', 'The system instructions tell OpenAI the rules it should follow. The user message tells it what the user wants it to do.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '417', '38', '10', 'The API key should be kept on the server because putting it in JavaScript would allow users to see it. The browser should call your server instead.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '418', '38', '11', 'Tokens are small pieces of the prompt and response. The number of tokens affects how much information you can send and how much the request costs.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '419', '38', '12', 'Text responses are easier for people to read while JSON is better when a program needs fields such as a score, name, or status.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '420', '38', '13', 'The application sends data to a backend endpoint and the backend sends a request to OpenAI. Then the returned information can be sent back to the application.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '421', '38', '14', 'Temperature controls how creative the response is. A lower temperature is useful if you want similar answers every time.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '422', '38', '15', 'The response should be checked before saving it because the AI could return unexpected information or invalid JSON.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '423', '38', '16', 'You can upload files for OpenAI to analyze, for example a PDF resume or a document.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '424', '38', '17', 'If an API call fails the application should catch the error instead of crashing. It can retry the request and show the user an error if it still fails.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '431', '39', '9', 'A system prompt tells the AI what kind of assistant it is and a user prompt contains the question.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '432', '39', '10', 'API keys should be hidden so users cannot copy them. They can be stored in a configuration file.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '433', '39', '11', 'Tokens are the words that OpenAI reads. Using fewer tokens normally makes the request smaller.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '434', '39', '12', 'JSON is a format with keys and values and normal text is just paragraphs.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '435', '39', '13', 'I would call OpenAI from the application and wait for the answer, then display the response.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '436', '39', '14', 'Temperature changes the quality of the response. Lower temperatures usually give safer answers.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '437', '39', '15', 'You should check the answer to make sure it looks correct.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '438', '39', '16', 'Files can be sent to the AI so it can read them.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '439', '39', '17', 'If there is an error I would show the error and allow the user to try the button again.', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, NULL ),
( '446', '40', '9', 'They are basically two different ways of asking the AI a question.', '1.00', NULL, 'The answer lacks detail on application-level instructions and user input. It needs to clearly distinguish between the two and elaborate on the importance of keeping them separate.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '447', '40', '10', 'It is fine to put the API key in the frontend as long as the variable has a difficult name.', '1.00', NULL, 'The response does not address the question about structured data, focusing instead on API keys. It lacks a clear explanation of the benefits of structured responses.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '448', '40', '11', 'Tokens are authentication codes used to log into OpenAI.', '1.00', NULL, 'The student misinterprets tokens and does not address the relevant factors for model selection. The answer lacks understanding of quality, latency, capabilities, and cost.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '449', '40', '12', 'JSON responses are always more accurate than text responses.', '1.00', NULL, 'The definition of AI hallucination is missing, and the student does not provide any effective mitigation techniques. Needs substantial clarification.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '450', '40', '13', 'JavaScript connects directly to ChatGPT and receives an answer.', '1.00', NULL, 'The answer does not address how to process documents for OpenAI. Instead, it focuses on JavaScript without relevant context about document processing.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '451', '40', '14', 'Temperature is the amount of processing power used by the AI.', '1.00', NULL, 'The answer is off-topic, misinterpreting the concept of conversation context with unrelated terminology about temperature. Needs to explain the importance of context in conversations.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '452', '40', '15', 'There is no need to validate the result because the API has already validated it.', '1.00', NULL, 'Misunderstands the need for validation and the role of tools or function calling. The answer lacks clarity on why an order status should not be invented by the model.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '453', '40', '16', 'Uploading a file trains the OpenAI model permanently with the information in that file.', '1.00', NULL, 'The student misses the critical point of API key security and discusses an incorrect interpretation of file uploading as training. Needs a correct understanding of security practices.', NULL, NULL, NULL, 'evaluated', NULL, NULL ),
( '454', '40', '17', 'If the API fails the application should keep calling it repeatedly until it works.', '1.00', NULL, 'The response is not relevant to a systematic evaluation process. A more structured approach to grading is needed, focusing on consistency and explanation.', NULL, NULL, NULL, 'evaluated', NULL, NULL );
